# swc-plugin-pre-paths

A [SWC](https://swc.rs) plugin to use [path mapping](https://www.typescriptlang.org/docs/handbook/module-resolution.html#path-mapping).
This may be needed in other plugins.

## Installation

**npm:**

```sh
npm i -D swc-plugin-pre-paths
```

**yarn:**

```sh
yarn add -D swc-plugin-pre-paths
```

You can check the compatibility of versions on https://plugins.swc.rs/

## Usage

Via `.swcrc`

```json
{
  "jsc": {
    "experimental": {
      "plugins": [
        [
          "swc-plugin-pre-paths",
          {
            "baseUrl": ".",
            "paths": {
              "app/*": ["./src/app/*"],
              "config/*": ["./src/app/_config/*"],
              "environment/*": ["./src/environments/*"],
              "shared/*": ["./src/app/_shared/*"],
              "helpers/*": ["./src/helpers/*"],
              "tests/*": ["./src/tests/*"]
            }
          }
        ]
      ]
    }
  }
}
```

## Limits

This don't support multiple fall back locations.

```jsonc
{
  "paths": {
    "*": ["*", "generated/*"] // ⛔ don't support
  }
}
```

use std::{env, fs, path::PathBuf};

use swc_core::ecma::{
    parser::{EsSyntax, Syntax},
    transforms::testing::test_fixture,
    visit::visit_mut_pass,
};
use swc_plugin_pre_paths::{Config, Injector};

fn syntax() -> Syntax {
    Syntax::Es(EsSyntax {
        jsx: true,
        ..Default::default()
    })
}

#[testing::fixture("tests/fixture/**/input.js")]
fn fixture(input: PathBuf) {
    let output = input.parent().unwrap().join("output.js");
    let config_path = input.parent().unwrap().join("config.json");

    let config_file = fs::File::open(config_path).expect("failed to open config");

    let config: Config = serde_json::from_reader(config_file).expect("invalid config");

    let cwd = env::current_dir().unwrap();

    test_fixture(
        syntax(),
        &|_| {
            visit_mut_pass(Injector::new(
                cwd.to_str().unwrap(),
                input.to_str().unwrap(),
                config.clone(),
            ))
        },
        &input,
        &output,
        Default::default(),
    );
}

{
  "paths": {
    "jquery": ["node_modules/jquery/dist/jquery"]
  }
}

